From 63244e253363b1677826df526bc7457ba845d9f0 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:40:02 +0100
Subject: [PATCH] applets/webbrowser: make Save page and View page source work

Nothing accepted downloads, so "Save page" did nothing, and the source
view URL was handed to the system, where no app can open it. Save pages
to the Downloads folder and show the source inside the widget instead.

BUG: 482273
---
 applets/webbrowser/qml/main.qml | 17 ++++++++++++++++-
 1 file changed, 16 insertions(+), 1 deletion(-)

diff --git a/applets/webbrowser/qml/main.qml b/applets/webbrowser/qml/main.qml
index 38c005eb0..3eca3356b 100644
--- a/applets/webbrowser/qml/main.qml
+++ b/applets/webbrowser/qml/main.qml
@@ -292,6 +292,19 @@ PlasmoidItem {
                 profile: WebEngineProfile {
                     storageName: Plasmoid.metaData.pluginId
                     offTheRecord: Plasmoid.configuration.privateBrowsing
+
+                    onDownloadRequested: download => download.accept()
+
+                    onDownloadFinished: download => {
+                        if (download.state !== WebEngineDownloadRequest.DownloadCompleted) {
+                            return;
+                        }
+                        infoButton.show(i18nc("@info:status a page or file was saved", "Saved"), "folder-download-symbolic",
+                                        i18nc("@info:tooltip", "%1 was saved in %2. Click to open the folder.", download.downloadFileName, download.downloadDirectory), function () {
+                            Qt.openUrlExternally("file://" + download.downloadDirectory);
+                            infoButton.dismiss();
+                        });
+                    }
                 }

                 readonly property bool useMinViewWidth : Plasmoid.configuration.useMinViewWidth
@@ -341,7 +354,9 @@ PlasmoidItem {
                 onNewWindowRequested: request => {
                     var url = request.requestedUrl;

-                    if (request.userInitiated) {
+                    if (url.toString().startsWith("view-source:")) {
+                        webview.url = url;
+                    } else if (request.userInitiated) {
                         Qt.openUrlExternally(url);
                     } else {
                         infoButton.show(i18nc("@info:status An unwanted popup was blocked", "Popup blocked"), "document-close-symbolic",
-- 
